use super::*;
fn role()->Role{Role{key:"session-claim".into(),pool:"shared64".into(),kind:"userspace".into(),units:BTreeSet::new(),cgroup:"/user.slice/session-1.scope".into(),per_instance:Some(16),parallel:Some(1),recovery:Some(0),aggregate:Some(16),funding:Value::Null,sources:vec![],images:vec![json!({"path":"/sealed/program","sha256":"exact"})],policy:Value::Null,current_owner:json!({}),grammar:json!([["/sealed/program"]]),unit_sources:json!({}),unit_profiles:json!({})}}
fn kernel()->Role{let mut r=role();r.key="global-kernel".into();r.kind="global-kernel".into();r.cgroup.clear();r}
fn process()->Value{json!({"pid":41,"parent_pid":1,"start_ticks":71,"flags":0,"kernel_thread":false,"cgroup":"/user.slice/session-1.scope","argv":["/sealed/program"],"image":{"path":"/sealed/program","device":3,"inode":9,"bytes":4}})}
fn images()->BTreeMap<String,Value>{BTreeMap::from([("/sealed/program".into(),json!({"path":"/sealed/program","device":3,"inode":9,"bytes":4,"sha256":"exact"}))])}
fn endpoint()->Value{json!({"processes":{"41":process()},"units":{},"installed_unit_files":{},"unit_sources":{},"cgroups":{"/":{},"/user.slice":{},"/user.slice/session-1.scope":{"memory.max":"16","memory.swap.max":"0","pids.max":"8","cgroup.procs":[41]}}})}
fn has(issues:&[Value],gate:&str)->bool{issues.iter().any(|v|v["gate"]==gate)}
#[test]fn non_horizon_process_omission_is_a_failed_gate(){let e=evaluate(&endpoint(),&[kernel()],&images());assert_eq!(e["issues"][0]["gate"],"unmapped-or-unbounded-process");assert_eq!(e["future_bound_accepted"],false);}
#[test]fn a_mapped_current_process_still_has_no_future_acceptance(){let e=evaluate(&endpoint(),&[role(),kernel()],&images());assert!(e["issues"].as_array().unwrap().is_empty(),"{e}");assert_eq!(e["candidate_current_containment_complete"],true);assert_eq!(e["future_bound_accepted"],false);}
#[test]fn ancestor_and_child_reservations_cannot_both_charge_the_same_process(){let parent=role();let mut child=role();child.key="child".into();child.cgroup.push_str("/worker");assert!(has(&future_arithmetic(&[parent,child,kernel()],43_603_734_528,2_684_354_560),"duplicate-ancestor-descendant-charge"));}
#[test]fn systemd_launched_child_cannot_inherit_its_parent_pid_reservation(){let mut p=process();p["parent_pid"]=json!(41);p["cgroup"]=json!("/system.slice/external-child.service");assert!(process_role(&p,&[role(),kernel()]).is_err());}
#[test]fn unknown_queued_owner_is_not_current_zero_demand(){let mut e=endpoint();e["units"]=json!({"unrelated-work.service":{"MainPID":"0","ControlPID":"0","Job":"42 start"}});let v=evaluate(&e,&[role(),kernel()],&images());assert!(has(v["issues"].as_array().unwrap(),"unknown-active-or-queued-owner"));}
#[test]fn inactive_installed_future_route_must_be_reserved(){let mut e=endpoint();e["installed_unit_files"]=json!({"ordinary-login.service":"disabled"});let v=evaluate(&e,&[role(),kernel()],&images());assert!(has(v["issues"].as_array().unwrap(),"unmapped-future-installed-launch-route"));}
#[test]fn collected_plugin_a_future_slot_cannot_be_omitted(){let p=json!({"retained_verification_roles":[{"unit":"jetstreamer-horizon-plugin-receipt-watcher-shard-a-v4-fsync.service","retained_cap_bytes":8u64<<30}]});let v=required_roles(&[role(),kernel()],&p);assert!(v.iter().any(|i|i["gate"]=="omitted-or-changed-retained-role"&&i["unit"]=="jetstreamer-horizon-plugin-receipt-watcher-shard-a-v4-fsync.service"));}
#[test]fn duplicate_global_kernel_claim_cannot_supply_double_credit(){let mut k=kernel();k.key="duplicate-kernel".into();assert!(has(&future_arithmetic(&[role(),kernel(),k],43_603_734_528,2_684_354_560),"one-global-kernel-claim"));}
#[test]fn historical_host_cannot_absorb_the_separate_input_promise(){let v=future_arithmetic(&[role(),kernel()],43_603_734_528+2_684_354_560,0);assert!(has(&v,"historical-host-input-split"));}
#[test]fn unbounded_session_or_daemon_cannot_become_zero_future_demand(){let mut r=role();r.parallel=None;assert!(has(&future_arithmetic(&[r,kernel()],43_603_734_528,2_684_354_560),"unknown-future-budget"));}
#[test]fn future_concurrency_and_simultaneous_recovery_share_one_peak(){let mut r=role();r.parallel=Some(2);r.recovery=Some(1);r.aggregate=Some(32);assert!(has(&future_arithmetic(&[r,kernel()],43_603_734_528,2_684_354_560),"future-peak-undercharged"));}
#[test]fn future_peak_arithmetic_overflow_rejects(){let mut r=role();r.per_instance=Some(u64::MAX);r.parallel=Some(2);assert!(has(&future_arithmetic(&[r,kernel()],43_603_734_528,2_684_354_560),"future-peak-undercharged"));}
#[test]fn root_outer_is_a_distinct_native16_charge(){let mut r=role();r.key="fixture-aggregate".into();r.pool="native16".into();r.aggregate=Some(512u64<<20);assert!(has(&required_roles(&[r,kernel()],&json!({"retained_verification_roles":[]})),"missing-separate-Root-outer-booking"));}
#[test]fn normal_remainder_does_not_become_free_after_seven_guards(){let mut r=role();r.pool="normal10".into();r.aggregate=Some(7u64<<30);assert!(has(&required_roles(&[r,kernel()],&json!({"retained_verification_roles":[]})),"normal10-remainder-unreconciled"));}
#[test]fn original199_cannot_move_into_native16(){let mut r=role();r.pool="native16".into();r.aggregate=Some(512u64<<20);assert!(required_roles(&[r,kernel()],&json!({"retained_verification_roles":[]})).iter().any(|i|i["gate"]=="omitted-or-changed-retained-role"&&i["unit"]=="jetstreamer-epoch199-backfill-20261102-controller-v1-r2.service"));}
#[test]fn changed_sdk_or_uploader_image_rejects_current_assignment(){let mut e=endpoint();e["processes"]["41"]["image"]["path"]=json!("/sealed/changed-uploader");let v=evaluate(&e,&[role(),kernel()],&images());assert!(has(v["issues"].as_array().unwrap(),"unmapped-or-unbounded-process"));}
#[test]fn same_path_but_changed_mapped_inode_rejects(){let mut e=endpoint();e["processes"]["41"]["image"]["inode"]=json!(10);let v=evaluate(&e,&[role(),kernel()],&images());assert!(has(v["issues"].as_array().unwrap(),"unmapped-or-unbounded-process"));}
#[test]fn changed_argv_cannot_hide_in_a_funded_cgroup(){let mut e=endpoint();e["processes"]["41"]["argv"]=json!(["/sealed/program","--new-unqualified-role"]);let v=evaluate(&e,&[role(),kernel()],&images());assert!(has(v["issues"].as_array().unwrap(),"unmapped-or-unbounded-process"));}
#[test]fn missing_cgroup_membership_or_swap_limit_rejects(){let mut e=endpoint();e["cgroups"]["/user.slice/session-1.scope"]["cgroup.procs"]=json!([]);assert!(!evaluate(&e,&[role(),kernel()],&images())["issues"].as_array().unwrap().is_empty());e["cgroups"]["/user.slice/session-1.scope"]["cgroup.procs"]=json!([41]);e["cgroups"]["/user.slice/session-1.scope"]["memory.swap.max"]=json!("max");assert!(!evaluate(&e,&[role(),kernel()],&images())["issues"].as_array().unwrap().is_empty());}
#[test]fn containment_only_fixture_cannot_be_promoted_to_production_liveness(){let v=json!({"successful_production_upload_under_cap_qualified":true,"full_readback_verified":true,"canonical_sidecar_committed":true,"containment_only_fixture":true,"selected_coordinator_sha256":"1eede7d15cec7e5b1907ee44328caf2b20457ca8513472ca17e83fe3e08f9087","selected_uploader_sha256":"7b21414c1c105cefb18f5bf3ca8bb96759c14c529ea42232a70835bdc864b990","actual_transport_readback_sidecar_evidence":[]});assert!(validate_production_liveness(&v).is_err());}
#[test]fn claimed_production_success_with_no_actual_evidence_rejects(){let v=json!({"successful_production_upload_under_cap_qualified":true,"full_readback_verified":true,"canonical_sidecar_committed":true,"containment_only_fixture":false,"selected_coordinator_sha256":"1eede7d15cec7e5b1907ee44328caf2b20457ca8513472ca17e83fe3e08f9087","selected_uploader_sha256":"7b21414c1c105cefb18f5bf3ca8bb96759c14c529ea42232a70835bdc864b990","actual_transport_readback_sidecar_evidence":[]});assert!(validate_production_liveness(&v).is_err());}
#[test]fn same_cap_with_stale_iid_or_pid_birth_rejects(){let mut r=role();r.units.insert("login.service".into());r.current_owner=json!({"login.service":{"unit":"login.service","invocation_id":"old","main_pid":"41","start_ticks":70}});let mut e=endpoint();e["units"]=json!({"login.service":{"Id":"login.service","ActiveState":"active","SubState":"running","NRestarts":"0","ControlPID":"0","InvocationID":"new","MainPID":"41","ControlGroup":"/user.slice/session-1.scope"}});assert!(validate_current_owner(&r,&e).is_err());e["units"]["login.service"]["InvocationID"]=json!("old");assert!(validate_current_owner(&r,&e).is_err());}
#[test]fn changed_dropin_or_native_profile_cannot_borrow_old_policy(){let mut r=role();r.units.insert("login.service".into());r.unit_sources=json!({"login.service":{}});let mut e=endpoint();e["units"]=json!({"login.service":{"LoadState":"loaded","MainPID":"0","ControlPID":"0","MemoryMax":"16","MemorySwapMax":"0","TasksMax":"8","Delegate":"no","KillMode":"control-group","ExecStart":"/sealed/program"}});r.unit_profiles=json!({"login.service":e["units"]["login.service"]});e["unit_sources"]=json!({"login.service":{"/etc/systemd/system/login.service.d/changed.conf":{"sha256":"changed"}}});assert!(validate_current_owner(&r,&e).unwrap_err().to_string().contains("drop-in"));e["unit_sources"]["login.service"]=json!({});e["units"]["login.service"]["MemoryMax"]=json!("32");assert!(validate_current_owner(&r,&e).unwrap_err().to_string().contains("profile"));}

#[test]fn active_non_service_units_need_role_assignment_even_without_pids(){for name in["session-2.scope","user-2.slice","ordinary.timer","ordinary.socket"]{let mut e=endpoint();e["units"][name]=json!({"ActiveState":"active","MainPID":"0","ControlPID":"0","Job":""});let v=evaluate(&e,&[role(),kernel()],&images());assert!(has(v["issues"].as_array().unwrap(),"unknown-active-or-queued-owner"),"{name}");}}
